CREATE TABLE Users(UserId INT IDENTITY(1,1) PRIMARY KEY,FirstName NVARCHAR(30) NOT NULL,LastName NVARCHAR(30) NOT NULL,UserName NVARCHAR(30) NOT NULL UNIQUE,Password NVARCHAR(30) NOT NULL,NickName NVARCHAR(30) NOT NULL,UserType NVARCHAR(10) NOT NULL,Coins INT NOT NULL);
CREATE TABLE Clubs(ClubId INT IDENTITY(1,1) PRIMARY KEY,ClubName NVARCHAR(50) NOT NULL,League NVARCHAR(20) NOT NULL);
CREATE TABLE Games(GameId INT IDENTITY(1,1) PRIMARY KEY,GameDate DATETIME NOT NULL,League NVARCHAR(20) NOT NULL,ClubAId INT NOT NULL,ClubBId INT NOT NULL,GameResult NVARCHAR(10) NOT NULL,FOREIGN KEY(ClubAId) REFERENCES Clubs(ClubId),FOREIGN KEY(ClubBId) REFERENCES Clubs(ClubId));
CREATE TABLE Bets(BetId INT IDENTITY(1,1) PRIMARY KEY,UserId INT NOT NULL,GameId INT NOT NULL,BetDate DATETIME NOT NULL,BetCoins INT NOT NULL,BetClubId INT NOT NULL,BetResult INT NOT NULL,FOREIGN KEY(UserId) REFERENCES Users(UserId),FOREIGN KEY(GameId) REFERENCES Games(GameId),FOREIGN KEY(BetClubId) REFERENCES Clubs(ClubId));
